SELECT COALESCE(o.external_order_id, 'ORD-' || o.order_id::TEXT) AS orderId, p.account_id AS accountId, i.ticker AS symbol, o.side AS side, CAST(o.quantity AS INTEGER) AS quantity, o.price AS price,
CASE WHEN o.status = 'FILLED' THEN COALESCE(o.executed_price, o.price) ELSE NULL END AS executedPrice, o.status AS status, o.idempotency_key AS idempotencyKey, o.created_at AS createdOn, CASE WHEN o.status = 'FILLED' THEN o.settlement_amount ELSE NULL END AS settlementAmount FROM orders o INNER JOIN portfolio p ON p.portfolio_id = o.portfolio_id INNER JOIN instruments i ON i.instrument_id = o.instrument_id WHERE p.account_id = #{accountId}
AND o.status = #{status}
AND o.created_at >= #{from}
AND o.created_at <= #{to}
ORDER BY o.created_at DESC

